const BY_ID = new Map(SUBCATEGORIES.map((s) => [s.id, s]));
const BY_NAME = new Map<string, Subcategory>();
for (const s of SUBCATEGORIES) {
  for (const n of [s.en, s.id, ...s.aliases]) BY_NAME.set(n.trim().toLowerCase(), s);
}

export function subcategoryById(id: string): Subcategory | undefined {
  return BY_ID.get(id);
}

/** Maps a stored helper service (legacy English name or id) to a subcategory id. */
export function serviceToId(name: unknown): string | null {
  if (typeof name !== "string") return null;
  return BY_NAME.get(name.trim().toLowerCase())?.id ?? null;
}